package org.firstinspires.ftc.teamcode.config;

import com.pedropathing.api.PoseFactory;
import com.pedropathing.math.Pose;

// Generated by refract-suite ftc-construct. Survives between OpModes while the Robot Controller app runs.
// Written by the auto at INIT/loop and by teleop each loop, so a restarted teleop resumes from the last
// pose. Null/false means no auto has run this session.
public final class MatchState {
    public enum Alliance { RED, BLUE }

    public static volatile Alliance alliance = null;
    public static volatile Pose pose = null;
    // when TeleOp last wrote `pose` (0 = the auto wrote it). A TeleOp restarted within RESUME_MS (a mid-match
    // disconnect) resumes from it; later than that it is a practice run and starts from the start corner.
    public static volatile long teleOpPoseMs = 0;
    public static final long RESUME_MS = 5 * 60 * 1000;

    private MatchState() {}

    // Paths and poses are drawn for BLUE. BIOBUZZ red is the 180-degree rotation about the field centre
    // (never mirrorX, which is DECODE-style mirroring).
    public static PoseFactory poseFactory() {
        return alliance == Alliance.RED
                ? PoseFactory.degrees().mirrorAroundPoint(Field.CENTER, Field.CENTER)
                : PoseFactory.degrees();
    }
}
